// true when the value is inside the window for this zone; a NAN bound
// is simply not applied, and an uncomputable value passes (matching
// the NaN policy this was tuned with: pass).
inline bool pass(int combo, int charge, double v,
                 const double lo[13][2], const double hi[13][2]) {
    if (combo < 0 || combo > 12 || charge < 0 || charge > 1) return false;
    if (std::isnan(v)) return true;
    const double l = lo[combo][charge];
    const double h = hi[combo][charge];
    if (!std::isnan(l) && v < l) return false;
    if (!std::isnan(h) && v > h) return false;
    return true;
}

